import shutil
import subprocess
from pathlib import Path

from agents import function_tool


@function_tool
def run_lnav_log_query(log_file: str, sql_query: str, timeout_seconds: int = 60) -> dict:
    path = Path(log_file)
    if not path.is_file():
        return {"error": f"log file not found: {log_file}"}
    query = sql_query.strip()
    if not query:
        return {"error": "sql_query must not be empty"}
    if not query.lower().startswith("select"):
        return {"error": "only SELECT queries are allowed"}
    if timeout_seconds < 1 or timeout_seconds > 300:
        return {"error": "timeout_seconds must be between 1 and 300"}
    lnav = shutil.which("lnav")
    if lnav is None:
        return {"error": "lnav is not installed on this host"}
    try:
        completed = subprocess.run(
            [lnav, "-n", "-c", f";{query}", str(path)],
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired:
        return {"error": f"query timed out after {timeout_seconds}s"}
    return {
        "exit_code": completed.returncode,
        "output": completed.stdout[-20000:],
        "stderr": completed.stderr[-4000:],
    }
